def evaluate(expr):
    """
    Evaluate an arithmetic expression containing integers, + - * /,
    parentheses and unary minus, honoring standard precedence.
    Returns a float. Raises ValueError on malformed input.
    """

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
            elif c in '+-*/()':
                tokens.append(c)
                i += 1
            elif c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                raise ValueError(f"Unexpected character: {c!r}")
        return tokens

    tokens = tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        value = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            rhs = parse_term()
            if op == '+':
                value += rhs
            else:
                value -= rhs
        return value

    def parse_term():
        # term := factor (('*' | '/') factor)*
        value = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero in expression")
                value /= rhs
        return value

    def parse_factor():
        # factor := ('+' | '-') factor | '(' expr ')' | number
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == '+':
            consume()
            return parse_factor()
        if tok == '-':
            consume()
            return -parse_factor()
        if tok == '(':
            consume()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume()
            return value
        if tok.isdigit():
            return float(consume())
        raise ValueError(f"Unexpected token: {tok!r}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token at end: {tokens[pos]!r}")
    return float(result)
