def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit() or (c == '.' and i + 1 < n and s[i + 1].isdigit()):
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            tokens.append(('num', float(s[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r}")
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise ValueError(f"Expected {kind}, got {self.peek()}")
        return self.next()

    def parse_expr(self):
        # expr := term (('+' | '-') term)*
        value = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.next()[0]
            rhs = self.parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term(self):
        # term := factor (('*' | '/') factor)*
        value = self.parse_factor()
        while self.peek() in ('*', '/'):
            op = self.next()[0]
            rhs = self.parse_factor()
            value = value * rhs if op == '*' else value / rhs
        return value

    def parse_factor(self):
        # factor := '-' factor | '(' expr ')' | number
        tok_kind = self.peek()
        if tok_kind == '-':
            self.next()
            return -self.parse_factor()
        if tok_kind == '+':
            self.next()
            return self.parse_factor()
        if tok_kind == '(':
            self.next()
            value = self.parse_expr()
            self.expect(')')
            return value
        if tok_kind == 'num':
            return self.next()[1]
        raise ValueError(f"Unexpected token: {tok_kind}")

    def expect_end(self):
        if self.pos != len(self.tokens):
            raise ValueError(f"Unexpected token: {self.peek()}")
