def evaluate(expr):
    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/':
            tokens.append(('OP', c))
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', c))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    parser = _Parser(tokens)
    return parser.parse()


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def take(self):
        token = self.peek()
        if token is not None:
            self.pos += 1
        return token

    def parse(self):
        value = self.expression()
        if self.peek() is not None:
            raise ValueError("Unexpected token")
        return float(value)

    def expression(self):
        value = self.term()

        while self.peek() is not None and self.peek()[0] == 'OP' and self.peek()[1] in ('+', '-'):
            op = self.take()[1]
            rhs = self.term()
            if op == '+':
                value += rhs
            else:
                value -= rhs

        return value

    def term(self):
        value = self.factor()

        while self.peek() is not None and self.peek()[0] == 'OP' and self.peek()[1] in ('*', '/'):
            op = self.take()[1]
            rhs = self.factor()
            if op == '*':
                value *= rhs
            elif op == '/':
                value /= rhs

        return value

    def factor(self):
        token = self.peek()

        if token is not None and token[0] == 'OP' and token[1] in ('+', '-'):
            op = self.take()[1]
            value = self.factor()
            return -value if op == '-' else value

        return self.primary()

    def primary(self):
        token = self.take()

        if token is None:
            raise ValueError("Unexpected end of expression")

        if token[0] == 'NUM':
            return token[1]

        if token[0] == 'LPAREN':
            value = self.expression()
            closing = self.take()
            if closing is None or closing[0] != 'RPAREN':
                raise ValueError("Expected closing parenthesis")
            return value

        raise ValueError("Unexpected token")
