        self.capacity = capacity
        self.cache = {}  # dict preserves insertion order (Python 3.7+)

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        value = self.cache.pop(key)
        self.cache[key] = value  # move to end (most recently used)
        return value

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            # evict least recently used (first item)
            oldest = next(iter(self.cache))
            self.cache.pop(oldest)
        self.cache[key] = value
```

Both `get` and `put` are O(1): dict operations are average O(1), and `next(iter(...))` grabs the first (oldest) key in O(1).

